  "anomaly_detected": true,
  "confidence": 0.78,
  "anomalies": [
    {
      "category": "wrong_value",
      "components": ["R3", "D2"],
      "pins": ["D2.2", "D2.1", "R3.1", "R3.2"],
      "nets": ["/Microcontroller/HEATER", "Net-(D2-K)", "GND"],
      "observed": "D2 is connected from the HEATER net through R3, valued 500kΩ, to GND. At a nominal 12 V heater output, this limits LED current to roughly 20 µA.",
      "expected": "For the specified visual heater-on indicator, a series resistance that provides clearly visible LED current is expected; 500kΩ is unusually large and is likely to make the indicator extremely dim or effectively invisible in normal ambient light.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"R3\") (value \"500k\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"4\") (name \"/Microcontroller/HEATER\") ... (node (ref \"D2\") (pin \"2\") (pinfunction \"A\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"14\") (name \"Net-(D2-K)\") ... (node (ref \"D2\") (pin \"1\") (pinfunction \"K\")) (node (ref \"R3\") (pin \"1\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"13\") (name \"GND\") ... (node (ref \"R3\") (pin \"2\"))"
        },
        {
          "source": "spec",
          "quote": "A status LED (`D2`) and series resistor (`R3`) are also on the `HEATER` net, so the heater output doubles as a visual \"heater on\" indicator"
        }
      ],
      "impact": "The heater output may energize normally, but the intended visual indication of heater operation is likely too dim to be useful.",
      "confidence": 0.78
    }
  ],
  "summary": "The main design appears consistent with the specification, but the 500kΩ series resistor on the heater-status LED is likely to underdrive it so severely that the visual heater-on indication is ineffective."
}

